export const VIEW_BOX = '266 237 503 547';
export const VB_W = 503;
export const VB_H = 547;

// The three parts light up in turn, left to right: the sweep the instrument
// makes across the disk. They dim rather than disappear between turns, so the
// thing still reads as the logo at any instant.
const BASE_OPACITY = 0.3;
const PULSE_WIDTH = 0.02;  // smaller = sharper travelling highlight
const PULSE_PEAK = 0.12;   // where inside its slot a part peaks
const CYCLE_MS = 1400;

/**
 * Indeterminate loader drawn with the SUNSCAN mark.
 *
 * `size` is the width in points; the height follows the mark's aspect ratio.
 */
export default function SunscanLoader({ size = 64, color = '#fff' }) {
  const width = size;
  const height = (size * VB_H) / VB_W;

  const progress = useSharedValue(0);

  useEffect(() => {
    progress.value = 0;
    progress.value = withRepeat(
      withTiming(1, { duration: CYCLE_MS, easing: Easing.linear }),
      -1,
      false
    );
    return () => cancelAnimation(progress);
  }, []);

  // One <Svg> per part, stacked on a shared viewBox, rather than animating SVG
  // props: plain View opacity behaves the same on every platform.
  return (
    <View style={{ width, height }}>
      {PATHS.map((d, index) => (
        <Part
          key={index}
          d={d}
          color={color}
          progress={progress}
          phase={index / PATHS.length}
          width={width}
          height={height}
        />
      ))}
    </View>
  );
}

function Part({ d, color, progress, phase, width, height }) {
  const style = useAnimatedStyle(() => {
    let distance = progress.value - phase;
    if (distance < 0) {
      distance += 1; // the wave wraps round instead of restarting from dark
    }
    const pulse = Math.exp(-((distance - PULSE_PEAK) ** 2) / PULSE_WIDTH);
    return { opacity: BASE_OPACITY + (1 - BASE_OPACITY) * pulse };
  });

  return (
    <Animated.View style={[{ position: 'absolute', left: 0, top: 0, width, height }, style]}>
      <Svg width={width} height={height} viewBox={VIEW_BOX}>
        <Path d={d} fill={color} fillRule="evenodd" />
      </Svg>
    </Animated.View>
  );
}
